import numpy as np
z=np.load('/app/output/initial.npz'); im=z['im']; d=z['d']; K=z['K']; E=z['E']; inv=np.linalg.inv(np.vstack([E,[0,0,0,1]])); fx,fy=K[0,0],K[1,1];cx,cy=K[0,2],K[1,2]
# roi, color rule
rois={'red':(285,140,350,198),'blue':(405,180,460,240),'green':(530,140,590,198),'yellow':(480,195,545,245)}
for n,(x0,y0,x1,y1) in rois.items():
 p=im[y0:y1,x0:x1].astype(int); R,G,B=p[:,:,0],p[:,:,1],p[:,:,2]
 if n=='red': m=(R>50)&(R>G*1.7)&(R>B*1.7)
 if n=='blue': m=(B>20)&(B>R*1.5)&(B>G*1.5)
 if n=='green': m=(G>18)&(G>R*1.5)&(G>B*1.5)
 if n=='yellow': m=(R>70)&(G>70)&(B<40)&(abs(R-G)<90)
 yy,xx=np.where(m); xx+=x0; yy+=y0; zz=d[yy,xx]; ok=(zz>0)&(zz<1); xx,yy,zz=xx[ok],yy[ok],zz[ok]
 C=np.column_stack(((xx-cx)*zz/fx,(yy-cy)*zz/fy,zz,np.ones(len(zz)))); X=C@inv.T
 print('\n',n,'n',len(xx),'pixbbox',np.min(xx),np.min(yy),np.max(xx),np.max(yy))
 for th in [0.045,0.048,0.049,0.050]:
  sel=X[:,2]>th
  if sum(sel)>0: print('z>',th,'n',sum(sel),'world med',np.median(X[sel,:3],axis=0),'xyq',np.quantile(X[sel,:2],[0,.5,1],axis=0))
 print('depth quantile',np.quantile(X[:,2],[0,.25,.5,.75,1]))
